# Created by OpenAI
"""Shared MoE arithmetic, tile-layout, asynchronous-copy, and reduction primitives."""
from triton.experimental import gluon
from triton.experimental.gluon import language as gl

@gluon.jit
def _sigmoid(x):
    return 1.0 / (1.0 + gl.exp(-x))

@gluon.jit
def _weight_offset_grouped(n, k, K: gl.constexpr):
    return n // 16 * (K * 16) + k // 16 * 256 + n % 16 * 16 + k % 16

@gluon.jit
def _sum(a, b):
    return a + b

@gluon.jit
def _physical_column(n, C: gl.constexpr):
    if C.gate:
        return gl.where(n < C.gate, n, n + C.weight_n // 2 - C.gate)
    return n
